1	export interface Item {
2	  type: string;
3	}
4	
5	export interface QuoteStep {
6	  op: "quote";
7	  items: Item[];
8	}
9	
10	export interface Scenario {
11	  customer: { yearsWithMHPCO: number };
12	  steps: QuoteStep[];
13	}
14	
15	export interface ScenarioOutput {
16	  results: unknown[];
17	}
18	
19	const PROCESSING_FEE = 5;
20	const FIRST_INSURANCE_SURCHARGE = 0.1;
21	
22	const BASE_PREMIUMS: Record<string, number> = {
23	  sword: 100,
24	  amulet: 60,
25	  staff: 80,
26	};
27	
28	const quotePremium = (step: QuoteStep): number => {
29	  const policyBasePremium = step.items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
30	  const firstInsuranceSurcharge = policyBasePremium * FIRST_INSURANCE_SURCHARGE;
31	  return policyBasePremium + firstInsuranceSurcharge + PROCESSING_FEE;
32	};
33	
34	export const runScenario = (scenario: Scenario): ScenarioOutput => ({
35	  results: scenario.steps.map((step) => ({ premium: quotePremium(step) })),
36	});
